//! Actual owned cache and strict startup factory refusal checks at OR70.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::crafting_finishes;
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn six_actual_items_two_manual_factories_and_sixty_seven_refusals(){
 let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let stat=symbols::load(&[Path::new(&dir)],"stat",None).unwrap();
 let cache=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&cache),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let stats=cache.files(2,200,None).unwrap().unwrap();
 let ids=[("dorgesh_lightbulb_nofilament",10980),("dorgesh_wire",10981),("dorgesh_light_bulb",10973),("chisel",1755),("serpentine_visage",12927),("serpentine_helm",12929)];
 let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for(_,id)in ids{defs.items.insert(id as u32,gielinor_cache::definitions::ItemType::decode(&items[&(id as u32)]).unwrap());}defs.stats.insert(12,gielinor_cache::definitions::StatType::decode(&stats[&12]).unwrap());
 let r=crafting_finishes(&objects,&stat,&defs).unwrap();assert_eq!((r.light_orb.first,r.light_orb.second,r.light_orb.output,r.light_orb.skill,r.light_orb.level,r.light_orb.base_xp,r.light_orb.members),(10980,10981,10973,12,87,104,true));let h=r.serpentine_helm;assert_eq!((h.exchange.tool,h.exchange.input,h.exchange.output,h.exchange.members,h.level,h.xp_tenths,h.ticks,h.exchange.animation),(1755,12927,12929,true,52,1200,1,None));assert!(h.failure.is_none());
 let mut refused=0;for(symbol,id)in ids{for case in 0..10{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Independent wrong item".into(),2=>{let v=d.items.get_mut(&(id as u32)).unwrap();v.members=!v.members;},3=>d.items.get_mut(&(id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>{o.insert(symbol.into(),id+100000);},_=>{o.remove(symbol);}}assert!(crafting_finishes(&o,&stat,&d).is_err(),"{symbol} case{case}");refused+=1;}}
 for case in 0..7{let mut d=copy(&defs);let mut s=stat.clone();match case{0=>{s.remove("crafting");},1=>{s.insert("crafting".into(),13);},2=>{d.stats.remove(&12);},3=>d.stats.get_mut(&12).unwrap().name="Wrong".into(),4=>d.stats.get_mut(&12).unwrap().unreleased=true,5=>d.stats.get_mut(&12).unwrap().min_level=0,6=>d.stats.get_mut(&12).unwrap().max_level=98,_=>unreachable!()}assert!(crafting_finishes(&objects,&s,&d).is_err());refused+=1;}
 assert_eq!(refused,67);assert_eq!(crafting_finishes(&objects,&stat,&defs).unwrap().serpentine_helm.exchange.output,12929);println!("PG_FINISH_BINDINGS actual_items=6 actual_stat=12 independently_refused=67");
}
